'use strict';
const GuideExperience={
 unique(values,allowed,max=3){return [...new Set(values.filter(v=>allowed.includes(v)))].slice(0,max);},
 signature(aromas){const names={Citrus:'Citrus Scout',Pine:'Forest Dweller',Floral:'Floral Explorer',Earthy:'Earthy Original',Spicy:'Spice Seeker',Woody:'Woodland Wanderer',Herbal:'Herbal Enthusiast',Fresh:'Fresh Perspective'};return aromas.length?{name:names[aromas[0]]||'The Curious Nose',description:aromas.length===1?'Your starting note is '+aromas[0].toLowerCase()+'. Follow the vocabulary and see what else you discover.':'A '+aromas.map(a=>a.toLowerCase()).join(' + ')+' point of view. Different references, one very personal combination.'}:{name:'Find your signature.',description:'Choose up to three aroma families to make your own card.'};},
 plan(params,cities){const amount=(key,max,defaultValue)=>{const raw=params.get(key);if(raw===null||raw==='')return defaultValue;const n=Number(raw);return Number.isFinite(n)&&n>=0&&n<=max?Math.round(n*100)/100:defaultValue;};return {city:cities.includes(params.get('city'))?params.get('city'):cities[0],subtotal:amount('sub',10000,60),tax:amount('tax',10000,null),tip:amount('tip',1000,0),fulfillment:params.get('mode')==='pickup'?'pickup':'delivery'};},
 shareURL(base,kind,state){const u=new URL('index.html',base);if(kind==='atlas'){u.searchParams.set('shortlist',state.join(','));u.hash='discovery';}if(kind==='terpenes'){u.searchParams.set('aromas',state.join(','));u.hash='scent-studio';}if(kind==='delivery'){u.searchParams.set('city',state.city);u.searchParams.set('sub',String(state.subtotal));if(state.tax!==null)u.searchParams.set('tax',String(state.tax));u.searchParams.set('tip',String(state.tip));u.searchParams.set('mode',state.fulfillment);u.hash='plan-sharing';}if(kind==='quiz'){u.searchParams.set('challenge','1');u.hash='knowledge';}return u.href;}
};
if(typeof module!=='undefined'&&module.exports)module.exports=GuideExperience;
if(typeof document!=='undefined'){
const D=JSON.parse(document.getElementById('site-data').textContent),$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],params=new URLSearchParams(location.search);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n),allowedAromas=['Citrus','Pine','Floral','Earthy','Spicy','Woody','Herbal','Fresh'];
let shortlist=[],aromas=[],quizIndex=0,quizScore=0,quizAnswered=false;
const storage={get(){try{return JSON.parse(localStorage.getItem('bayleaf-shortlist')||'[]');}catch{return[];}},set(v){try{localStorage.setItem('bayleaf-shortlist',JSON.stringify(v));}catch{}}};
const initial=storage.get();shortlist=GuideExperience.unique(Array.isArray(initial)?initial:[],D.brands.map(b=>b.id));
if(params.has('shortlist'))shortlist=GuideExperience.unique(params.get('shortlist').split(','),D.brands.map(b=>b.id));
function shortlistRender(){if(!$('#shortlist-results'))return;storage.set(shortlist);$('#shortlist-title').textContent=shortlist.length?'Your '+shortlist.length+'-brand edit.':'A clean page.';const reason=$('#discovery-interest')?.value||'format';$('#shortlist-results').innerHTML=shortlist.map((id,i)=>{const b=D.brands.find(b=>b.id===id);const note=reason==='origin'?b.region+'. '+b.text:reason==='details'?b.question:b.formats.join(' · ')+'. '+b.short;return '<article class="shortlist-item"><span class="shortlist-number">0'+(i+1)+'</span><div><h4><a href="brand-'+b.id+'.html">'+escape(b.name)+'</a></h4><p>'+escape(note)+'</p></div><button data-remove-shortlist="'+b.id+'" aria-label="Remove '+escape(b.name)+'">×</button></article>';}).join('')+(shortlist.length?'<button class="text-button small" id="shortlist-clear">Clear saved shortlist</button>':'<p>Choose a format to start again, or add a brand from any profile.</p>');$$('[data-remove-shortlist]').forEach(b=>b.addEventListener('click',()=>{shortlist=shortlist.filter(id=>id!==b.dataset.removeShortlist);shortlistRender();}));$('#shortlist-clear')?.addEventListener('click',()=>{shortlist=[];shortlistRender();});}
function discover(){const format=$('#discovery-format').value;shortlist=D.brands.filter(b=>b.formats.includes(format)).slice(0,3).map(b=>b.id);shortlistRender();}
$('#discovery-build')?.addEventListener('click',discover);$('#discovery-interest')?.addEventListener('change',shortlistRender);
if($('#shortlist-results')){if(!shortlist.length&&!params.has('shortlist')&&!localStorageAvailableSaved())discover();else shortlistRender();}
function localStorageAvailableSaved(){try{return localStorage.getItem('bayleaf-shortlist')!==null;}catch{return false;}}
$$('[data-add-shortlist]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.addShortlist;let list=storage.get();list=GuideExperience.unique(Array.isArray(list)?list:[],D.brands.map(b=>b.id));const feedback=b.parentElement.querySelector('.share-feedback');if(!list.includes(id)&&list.length>=3){feedback.innerHTML='Your list already has three brands. <a href="index.html#discovery">Edit your shortlist</a> to make room.';return;}list=GuideExperience.unique([...list,id],D.brands.map(b=>b.id));storage.set(list);feedback.innerHTML='Saved in this browser. <a href="'+escape(GuideExperience.shareURL(location.href,'atlas',list))+'">Open and share your shortlist ↗</a>';}));
function scentRender(){aromas=GuideExperience.unique($$('[data-aroma][aria-pressed="true"]').map(b=>b.dataset.aroma),allowedAromas);if(!$('#scent-name'))return;const s=GuideExperience.signature(aromas);$('#scent-name').textContent=s.name;$('#scent-description').textContent=s.description;$('#scent-symbol').textContent=aromas.length?aromas.map(a=>String(allowedAromas.indexOf(a)+1).padStart(2,'0')).join(' / '):'01 / 08';$('#scent-tags').innerHTML=aromas.map(a=>'<span class="tag">'+escape(a)+'</span>').join('');const matches=D.terpenes.filter(t=>t.aromas.some(a=>aromas.includes(a)));$('#scent-matches').className='scent-matches';$('#scent-matches').innerHTML=matches.length?'<p>Follow these compound notes:</p>'+matches.map(t=>'<a href="terpene-'+t.id+'.html">'+escape(t.name)+' ↗</a>').join(''):'';}
document.addEventListener('aromas-changed',scentRender);
if($('#scent-name')){if(params.has('aromas')){const restored=GuideExperience.unique(params.get('aromas').split(','),allowedAromas);restored.forEach(a=>$('[data-aroma="'+a+'"]')?.click());}scentRender();}
function currentPlan(){return{city:$('#city')?.value||D.cities[0].id,subtotal:$('#subtotal')?.value.trim()===''?NaN:Number($('#subtotal')?.value),tax:$('#tax')?.value.trim()===''?null:Number($('#tax')?.value),tip:Number($('#tip')?.value||0),fulfillment:$('#fulfillment')?.value||'delivery'};}
function planResult(p){return GuideMath.budget({...p,fee:D.live.delivery.fee,minimum:D.live.delivery.minimum});}
function planRender(){if(!$('#ticket-total'))return;const p=currentPlan();$('#ticket-city').textContent=D.cities.find(c=>c.id===p.city)?.name||'Another city';try{const r=planResult(p);$('#ticket-total').textContent=money(r.total);$('#ticket-label').textContent=r.preTax?'Planning subtotal · before tax':'Planning total · entered tax included';$('#ticket-facts').innerHTML=[['Fulfillment',p.fulfillment==='pickup'?'Pickup':'Delivery'],['Product subtotal',money(p.subtotal)],['Tax',p.tax===null?'Not entered':money(p.tax)],['Delivery fee',money(r.delivery)],['Optional tip',money(p.tip)],['Source checked',(D.live.last_success||'').slice(0,10)]].map(([a,b])=>'<div class="ticket-row"><span>'+escape(a)+'</span><strong>'+escape(b)+'</strong></div>').join('')+(r.belowMinimum?'<p><strong>Below published delivery minimum.</strong></p>':'');}catch(e){$('#ticket-total').textContent='Check inputs';$('#ticket-label').textContent=e.message;$('#ticket-facts').textContent='Correct the planner fields before sharing.';}}
if($('#ticket-total')){if(params.has('city')||params.has('sub')){const p=GuideExperience.plan(params,D.cities.map(c=>c.id).concat('other'));for(const [id,value] of Object.entries({city:p.city,subtotal:p.subtotal,tax:p.tax??'',tip:p.tip,fulfillment:p.fulfillment})){const el=$('#'+id);el.value=value;el.dispatchEvent(new Event(id==='city'?'change':'input'));}}['city','subtotal','tax','tip','fulfillment'].forEach(id=>$('#'+id)?.addEventListener(id==='city'?'change':'input',planRender));planRender();}
function tripRender(){const mins=Number($('#trip-minutes').value),cost=Number($('#trip-cost').value),fee=D.live.delivery.fee;if(!Number.isFinite(mins)||!Number.isFinite(cost)||mins<0||mins>1440||cost<0||cost>1000||$('#trip-minutes').value===''||$('#trip-cost').value===''){$('#trip-result').textContent='Enter a round trip from 0–1,440 minutes and a travel cost from $0–$1,000.';return;}const delta=Math.abs(cost-fee);$('#trip-result').innerHTML='<p>Your estimated pickup trip</p><div class="big">'+Math.round(mins)+' min · '+money(cost)+'</div><p>The published delivery fee is '+money(fee)+'. '+(delta<.005?'The fee and your entered travel cost are equal.':cost>fee?'That is '+money(delta)+' less than your travel cost.':'That is '+money(delta)+' more than your travel cost.')+'</p><p>Product costs, taxes and tips are separate. This does not estimate delivery time.</p>';}
['trip-minutes','trip-cost'].forEach(id=>$('#'+id)?.addEventListener('input',tripRender));if($('#trip-result'))tripRender();
function payload(kind){let title,text,url,rows=[];if(kind==='atlas'){if(!shortlist.length)throw Error('Add at least one brand before sharing.');title='My BAYLEAF shortlist';text='My Bay Area brand research edit: '+shortlist.map(id=>D.brands.find(b=>b.id===id).name).join(', ')+'. What is on yours?';url=GuideExperience.shareURL(location.href,kind,shortlist);rows=shortlist.map(id=>{const b=D.brands.find(b=>b.id===id);return[b.name,b.formats.join(' · ')+' | '+b.region];});}else if(kind==='terpenes'){if(!aromas.length)throw Error('Choose at least one aroma before sharing.');title=GuideExperience.signature(aromas).name;text='My NOSE NOTES signature: '+aromas.join(' + ')+'. What does your nose love?';url=GuideExperience.shareURL(location.href,kind,aromas);rows=aromas.map(a=>[a,D.terpenes.filter(t=>t.aromas.includes(a)).map(t=>t.name).join(', ')]);}else if(kind==='delivery'){const p=currentPlan(),r=planResult(p);title='My '+(D.cities.find(c=>c.id===p.city)?.name||'local')+' plan';text='A DOORSTEP SJ planning '+(r.preTax?'subtotal before tax':'total with entered tax')+' of '+money(r.total)+'. Review the assumptions and make your own.';url=GuideExperience.shareURL(location.href,kind,p);rows=[['Planning '+(r.preTax?'subtotal before tax':'total'),money(r.total)],['Products / Tax',money(p.subtotal)+' / '+(p.tax===null?'Not included':money(p.tax))],['Fee / Optional tip',money(r.delivery)+' / '+money(p.tip)],['Fulfillment',p.fulfillment==='pickup'?'Pickup':'Delivery']];}else{title=D.brandName+' knowledge check';text='I scored '+quizScore+' out of '+D.quiz.length+' on the '+D.brandName+' knowledge check. What will you score?';url=GuideExperience.shareURL(location.href,'quiz',null);}return{title,text,url,rows};}
function feedbackFor(button){return button.closest('.knowledge-box,.article-action')?.querySelector('.share-feedback')||button.closest('.share-controls')?.nextElementSibling;}
async function copy(data,feedback){try{await navigator.clipboard.writeText(data.url);feedback.textContent='Link copied. It opens this selection so someone else can make their own.';}catch{feedback.textContent='Copy this link:';const input=document.createElement('input');input.readOnly=true;input.value=data.url;input.setAttribute('aria-label','Share link');feedback.append(input);input.select();}}
$$('[data-share],[data-copy]').forEach(button=>button.addEventListener('click',async()=>{const feedback=feedbackFor(button);try{const data=payload(button.dataset.share||button.dataset.copy);if(button.dataset.share&&navigator.share){try{await navigator.share({title:data.title,text:data.text,url:data.url});feedback.textContent='Your result is ready to share.';}catch(e){if(e.name!=='AbortError')await copy(data,feedback);}}else await copy(data,feedback);}catch(e){feedback.textContent=e.message;}}));
function wrapped(ctx,text,x,y,width,lineHeight,maxLines=5){const words=text.split(/\s+/);let line='',n=0;for(const word of words){if(ctx.measureText(line+word).width>width&&line){ctx.fillText(line.trim(),x,y);y+=lineHeight;n++;line='';if(n>=maxLines)return y;}line+=word+' ';}if(line)ctx.fillText(line.trim(),x,y);return y+lineHeight;}
async function download(kind,feedback){const data=payload(kind),c=document.createElement('canvas');c.width=1200;c.height=1400;const ctx=c.getContext('2d');const theme=kind==='atlas'?['#fffefa','#22241f','#ef4d2f']:kind==='terpenes'?['#d0ef46','#242820','#242820']:['#edf3fd','#172c50','#2457ce'];ctx.fillStyle=theme[0];ctx.fillRect(0,0,1200,1400);ctx.fillStyle=theme[2];ctx.fillRect(65,65,80,12);ctx.fillStyle=theme[1];ctx.font='bold 37px Arial';ctx.fillText(D.brandName,65,140);ctx.font='22px Arial';ctx.fillText('SAN JOSE & THE BAY AREA  /  21+',65,183);ctx.font='bold 70px Georgia';let y=wrapped(ctx,data.title,65,300,1070,80,2)+30;ctx.font='28px Arial';y=wrapped(ctx,data.text,65,y,1050,43,4)+30;for(const [a,b] of data.rows){ctx.strokeStyle=theme[1]+'33';ctx.beginPath();ctx.moveTo(65,y);ctx.lineTo(1135,y);ctx.stroke();ctx.font='bold 33px Arial';y=wrapped(ctx,a,65,y+49,1070,40,2);ctx.font='27px Arial';y=wrapped(ctx,b,65,y+5,1070,37,2)+22;}ctx.fillStyle=theme[1];ctx.font='bold 26px Arial';ctx.fillText('MAKE YOUR OWN AT',65,1180);ctx.font='23px Arial';wrapped(ctx,location.host,65,1220,1070,32,2);ctx.font='20px Arial';ctx.fillText('Sponsored by '+(kind==='delivery'?'Purple Lotus Weed Delivery in San Jose':'Purple Lotus'),65,1300);ctx.font='18px Arial';ctx.fillText((kind==='delivery'?'Planning snapshot, not an order. ':kind==='terpenes'?'Aroma preferences, not an effects prediction. ':'Research shortlist, not stock or a quality rating. ')+'Source check: '+(D.live.last_success||'').slice(0,10),65,1340);const blob=await new Promise(resolve=>c.toBlob(resolve,'image/png'));if(!blob)throw Error('Your browser could not create the image. Use Copy link instead.');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=D.brandName.toLowerCase().replace(/\s+/g,'-')+'-my-card.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);feedback.textContent='Card downloaded. Copy the link too so someone can reopen your exact inputs.';}
$$('[data-download]').forEach(button=>button.addEventListener('click',async()=>{const f=feedbackFor(button);try{await download(button.dataset.download,f);}catch(e){f.textContent=e.message;}}));
function quizRender(){const questions=D.quiz;if(!questions?.length||!$('#quiz-question'))return;quizAnswered=false;$('#quiz-next').hidden=true;$('#quiz-restart').hidden=true;$('#quiz-share').hidden=true;$('#quiz-explanation').textContent='';$('#quiz-score').textContent=quizScore+' correct';if(quizIndex===questions.length){$('#quiz-progress').textContent='Knowledge check complete';$('#quiz-question').textContent=quizScore+' / '+questions.length+'. '+(quizScore===questions.length?'You know your stuff.':'A few more useful things to know.');$('#quiz-choices').innerHTML='';$('#quiz-explanation').textContent='Pass the challenge along, then explore the guides for the detail behind the answers.';$('#quiz-restart').hidden=false;$('#quiz-share').hidden=false;return;}const q=questions[quizIndex];$('#quiz-progress').textContent='Question '+(quizIndex+1)+' of '+questions.length;$('#quiz-question').textContent=q.question;$('#quiz-choices').innerHTML=q.choices.map((c,i)=>'<button data-answer="'+i+'">'+escape(c)+'</button>').join('');$$('[data-answer]').forEach(b=>b.addEventListener('click',()=>{if(quizAnswered)return;quizAnswered=true;const correct=Number(b.dataset.answer)===q.answer;if(correct)quizScore++;$$('[data-answer]').forEach(x=>{x.disabled=true;if(Number(x.dataset.answer)===q.answer)x.classList.add('correct');});if(!correct)b.classList.add('incorrect');$('#quiz-score').textContent=quizScore+' correct';$('#quiz-explanation').textContent=(correct?'Correct. ':'The answer is “'+q.choices[q.answer]+'”. ')+q.explanation;$('#quiz-next').textContent=quizIndex===questions.length-1?'See my result':'Next question';$('#quiz-next').hidden=false;}));}
$('#quiz-next')?.addEventListener('click',()=>{quizIndex++;quizRender();$('#quiz-question').setAttribute('tabindex','-1');$('#quiz-question').focus({preventScroll:true});});$('#quiz-restart')?.addEventListener('click',()=>{quizIndex=quizScore=0;quizRender();});if($('[data-quiz]')){$('.knowledge').id='knowledge';quizRender();}
$('#glossary-search')?.addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase();let count=0;$$('[data-term]').forEach(d=>{d.hidden=!d.dataset.term.includes(q);if(!d.hidden)count++;if(q&& !d.hidden)d.open=true;else if(!q)d.open=false;});$('#glossary-empty').hidden=count>0;});
}
